  Ltac shell_intros :=
    intros ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m l r n lo
           A2 N0 LL LR B1 F1 B2 F2 ACC1 ACC2 SV1 SV2 ST0 CEIL LO MI AC N40 INM1 INM2 DJ1 DJ2;
    acb;
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
    pose proof (bv_unsigned_in_range 64 a0) as A0R; unfold bv_modulus in A0R; change (2 ^ Z.of_N 64) with (2^64) in A0R;
    pose proof (bv_unsigned_in_range 64 a1) as A1R; unfold bv_modulus in A1R; change (2 ^ Z.of_N 64) with (2^64) in A1R;
    assert (NA2 : bv_unsigned a2 = n) by (subst a2; apply unsigned_lit; lia);
    assert (LB1 : Z.of_nat (length (map b8 l)) = n) by (rewrite length_map; exact LL);
    assert (LB2 : Z.of_nat (length (map b8 r)) = n) by (rewrite length_map; exact LR);
    pose proof INM1 as INM1'; unfold in_app_mem, AHI_LO, AAPP_HI in INM1'; rewrite ASHADOW_BASE_val in INM1';
    pose proof INM2 as INM2'; unfold in_app_mem, AHI_LO, AAPP_HI in INM2'; rewrite ASHADOW_BASE_val in INM2';
    assert (SRV : 2147450880 <= sh (hull_lo (bv_unsigned a0)) /\ sh (hull_hi (bv_unsigned a0 + n)) <= 17594333495296 + 16
                  /\ 2147450880 <= sh (hull_lo (bv_unsigned a1)) /\ sh (hull_hi (bv_unsigned a1 + n)) <= 17594333495296 + 16)
      by (unfold sh, hull_lo, hull_hi; rewrite ASHADOW_BASE_val; Z.div_mod_to_equations; lia);
    pose proof (bytes_at_bound _ _ _ _ B1) as SB1; rewrite length_map in SB1;
    pose proof (bytes_at_bound _ _ _ _ B2) as SB2; rewrite length_map in SB2;
    assert (C5 : rw_cells asegs m AINITED_CELL [C1 (b8 1); C1 (b8 1)]) by (eapply ACONST_cell; [exact AC | cbn; tauto]);
    unfold AINITED_CELL in C5; change (b8 1) with (Z_to_bv 8 1) in C5;
    pose proof (wmono_refl asegs m) as WM;
    pose proof SV1 as SV1m; unfold shvis in SV1m; pose proof SV2 as SV2m; unfold shvis in SV2m.

